export function createPlant(scale = 1) {
  const group = new THREE.Group();
  const potMat = new THREE.MeshStandardMaterial({ color: 0x2c2f38, roughness: 0.8 });
  const pot = new THREE.Mesh(new THREE.CylinderGeometry(0.13, 0.1, 0.24, 20), potMat);
  pot.position.y = 0.12;
  pot.castShadow = true;
  group.add(pot);
  const soil = new THREE.Mesh(new THREE.CylinderGeometry(0.115, 0.115, 0.01, 20), new THREE.MeshStandardMaterial({ color: 0x18120d, roughness: 1 }));
  soil.position.y = 0.24;
  group.add(soil);

  const leafMat = new THREE.MeshStandardMaterial({ color: 0x2f6b46, roughness: 0.7, side: THREE.DoubleSide });
  const leafMat2 = new THREE.MeshStandardMaterial({ color: 0x3f8256, roughness: 0.7, side: THREE.DoubleSide });
  for (let i = 0; i < 11; i++) {
    const a = (i / 11) * TAU + 0.4;
    const h = 0.45 + Math.random() * 0.4;
    const leaf = new THREE.Mesh(new THREE.SphereGeometry(0.1, 8, 6), i % 2 ? leafMat : leafMat2);
    leaf.scale.set(0.55, 1.7, 0.14);
    leaf.position.set(Math.cos(a) * 0.13, 0.28 + h * 0.5, Math.sin(a) * 0.13);
    leaf.rotation.set(Math.cos(a) * 0.45, -a, Math.sin(a) * 0.55);
    group.add(leaf);
  }
  group.scale.setScalar(scale);
  return group;
}

import * as THREE from 'three';
import { RoundedBoxGeometry } from '../vendor/addons/RoundedBoxGeometry.js';
import { createPS5, createController, createTV, createGameCase, createMug, createPlant } from './models.js';
import {
  woodTexture, wallTexture, rugTexture, cityTexture, posterTexture, neonTexture,
  textureFromCanvas, softShadowTexture, canvas2d, seeded, TAU,
} from './util.js';

const ROOM = { minX: -4.3, maxX: 4.3, minZ: -4.3, maxZ: 4.3, height: 3.25 };

function shadowPlane(texture, w, d, x, z, opacity = 0.75) {
  const mesh = new THREE.Mesh(
    new THREE.PlaneGeometry(w, d),
    new THREE.MeshBasicMaterial({ map: texture, transparent: true, opacity, depthWrite: false, toneMapped: false })
  );
  mesh.rotation.x = -Math.PI / 2;
  mesh.position.set(x, 0.016, z);
  mesh.renderOrder = 1;
  return mesh;
}

function makeCaseCover(title, sub, accent, accent2, motif) {
  const { canvas, ctx } = canvas2d(256, 340);
  const g = ctx.createLinearGradient(0, 0, 256, 340);
  g.addColorStop(0, accent);
  g.addColorStop(1, accent2);
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 256, 340);
  ctx.globalAlpha = 0.28;
  for (let i = 0; i < 7; i++) {
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(128, 150, 30 + i * 26, 0, TAU);
    ctx.stroke();
  }
  ctx.globalAlpha = 1;
  ctx.fillStyle = 'rgba(4,8,16,0.28)';
  ctx.fillRect(0, 0, 256, 340);
  if (motif === 'orb') {
    const rg = ctx.createRadialGradient(128, 138, 4, 128, 138, 58);
    rg.addColorStop(0, '#ffffff');
    rg.addColorStop(0.35, accent2);
    rg.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = rg;
    ctx.beginPath(); ctx.arc(128, 138, 58, 0, TAU); ctx.fill();
  } else if (motif === 'grid') {
    ctx.strokeStyle = 'rgba(130,235,255,0.8)';
    for (let i = 0; i < 6; i++) {
      const y = 170 + Math.pow(i / 5, 2) * 90;
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(256, y); ctx.stroke();
    }
  } else if (motif === 'ship') {
    ctx.fillStyle = 'rgba(255,255,255,0.9)';
    ctx.beginPath(); ctx.moveTo(128, 96); ctx.lineTo(158, 168); ctx.lineTo(128, 152); ctx.lineTo(98, 168); ctx.closePath(); ctx.fill();
  }
  ctx.fillStyle = '#ffffff';
  ctx.font = '700 30px "Space Grotesk", sans-serif';
  ctx.fillText(title, 18, 280);
  ctx.fillStyle = 'rgba(255,255,255,0.7)';
  ctx.font = '600 11px "Inter", sans-serif';
  ctx.fillText(sub, 19, 300);
  ctx.fillStyle = 'rgba(255,255,255,0.5)';
  ctx.fillRect(18, 310, 42, 2);
  return canvas;
}

