  // contact shadows
  scene.add(shadowPlane(tex.shadow, 3.6, 2.2, 0, 0.92, 0.85));
  scene.add(shadowPlane(tex.shadow, 2.4, 1.4, 0, -1.02, 0.7));
  scene.add(shadowPlane(tex.shadow, 5.2, 1.4, 0, -3.96, 0.9));
  scene.add(shadowPlane(tex.shadow, 1.2, 3.2, -4.0, 0.7, 0.7));
  scene.add(shadowPlane(tex.shadow, 1.2, 1.2, -3.55, -3.2, 0.6));
  scene.add(shadowPlane(tex.shadow, 0.7, 0.7, -2.85, 2.05, 0.55));

  // dust motes
  const dustGeo = new THREE.BufferGeometry();
  const dustCount = 180;
  const pos = new Float32Array(dustCount * 3);
  const speeds = new Float32Array(dustCount);
  for (let i = 0; i < dustCount; i++) {
    pos[i * 3] = (Math.random() - 0.5) * 8;
    pos[i * 3 + 1] = 0.4 + Math.random() * 2.4;
    pos[i * 3 + 2] = (Math.random() - 0.5) * 8;
    speeds[i] = 0.01 + Math.random() * 0.035;
  }
  dustGeo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  const dustMat = new THREE.PointsMaterial({
    color: 0xa8c4ff,
    size: 0.012,
    transparent: true,
    opacity: 0.4,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    sizeAttenuation: true,
  });
  const dust = new THREE.Points(dustGeo, dustMat);
  scene.add(dust);

  // lighting
  const hemi = new THREE.HemisphereLight(0x93a8e8, 0x1b120c, 0.42);
  scene.add(hemi);

  const moon = new THREE.DirectionalLight(0x9db9ff, 1.15);
  moon.position.set(6, 5.5, -0.6);
  moon.target.position.set(-1, 0.4, -1);
  moon.castShadow = true;
  moon.shadow.mapSize.set(1024, 1024);
  moon.shadow.camera.left = -6;
  moon.shadow.camera.right = 6;
  moon.shadow.camera.top = 6;
  moon.shadow.camera.bottom = -6;
  moon.shadow.camera.near = 0.5;
  moon.shadow.camera.far = 18;
  moon.shadow.bias = -0.0012;
  moon.shadow.normalBias = 0.02;
  scene.add(moon);
  scene.add(moon.target);

  const ambient = new THREE.AmbientLight(0x3b4666, 0.35);
  scene.add(ambient);

  // TV bias light
  const tvLight = new THREE.PointLight(0x2f6bff, 3.2, 6, 2);
  tvLight.position.set(0, 1.7, -3.35);
  scene.add(tvLight);

  // under-media glow
  const mediaGlow = new THREE.PointLight(0x2f6bff, 2.2, 3.2, 2);
  mediaGlow.position.set(0, 0.2, -3.4);
  scene.add(mediaGlow);

  // warm fill
  const warmFill = new THREE.PointLight(0xff9a5c, 2.4, 6, 2);
  warmFill.position.set(-1.5, 1.4, 2.6);
  scene.add(warmFill);

  let t = 0;
  const update = (dt) => {
    t += dt;
    const arr = dust.geometry.attributes.position.array;
    for (let i = 0; i < dustCount; i++) {
      arr[i * 3 + 1] += speeds[i] * dt;
      arr[i * 3] += Math.sin(t * 0.2 + i) * 0.0009;
      if (arr[i * 3 + 1] > 3.0) arr[i * 3 + 1] = 0.35;
    }
    dust.geometry.attributes.position.needsUpdate = true;
    const flicker = 0.92 + Math.sin(t * 17) * 0.03 + Math.sin(t * 5.3) * 0.05;
    neonGlow.intensity = 2.2 * flicker;
    candleLight.intensity = 1.3 + Math.sin(t * 9) * 0.12;
    tv.userData.glow.material.opacity = 0.42 + Math.sin(t * 1.6) * 0.04;
  };

  return {
    colliders,
    interactive,
    tv,
    screenMesh,
    ps5,
    controller,
    tvLight,
    windowLight,
    mediaGlow,
    update,
    bounds: ROOM,
  };
}

import { clamp } from './util.js';

const KEYMAP = {
  KeyW: 'up', ArrowUp: 'up',
  KeyS: 'down', ArrowDown: 'down',
  KeyA: 'left', ArrowLeft: 'left',
  KeyD: 'right', ArrowRight: 'right',
  Space: 'action', Enter: 'action', NumpadEnter: 'action',
  Escape: 'back', Backspace: 'back',
  KeyE: 'interact',
  KeyM: 'mute',
  KeyF: 'focus',
  KeyR: 'action2',
  ShiftLeft: 'sprint', ShiftRight: 'sprint',
};

export class Input {
  constructor() {
    this.held = new Set();
    this.edge = new Set();
    this.keys = new Set();
    this.axis = { x: 0, y: 0 };
    this.look = { x: 0, y: 0 };
    this.pad = {
      connected: false,
      name: '',
      moveX: 0,
      moveY: 0,
      lookX: 0,
      lookY: 0,
      prev: [],
    };
    this.tv = { x: 0.5, y: 0.5, active: false, down: false, downEdge: false };
    this.touchLookDX = 0;
    this.touchLookDY = 0;
    this.stick = { x: 0, y: 0, active: false };
    this.isTouch = matchMedia('(pointer: coarse)').matches || navigator.maxTouchPoints > 1;
    this._bindKeyboard();
    this._bindGamepad();
    this._bindTouch();
    if (this.isTouch) document.body.classList.add('touch');
    window.addEventListener('gamepadconnected', (e) => {
      this.pad.connected = true;
      this.pad.name = e.gamepad.id.replace(/\(.*?\)/g, '').trim().slice(0, 28);
      document.dispatchEvent(new CustomEvent('padchange', { detail: { connected: true, name: this.pad.name } }));
    });
    window.addEventListener('gamepaddisconnected', () => {
      this.pad.connected = false;
      document.dispatchEvent(new CustomEvent('padchange', { detail: { connected: false } }));
    });
  }

  _bindKeyboard() {
    window.addEventListener('keydown', (e) => {
      if (e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA')) return;
      const action = KEYMAP[e.code];
      if (!action) return;
      if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space'].includes(e.code)) e.preventDefault();
      if (e.repeat) return;
      this.keys.add(e.code);
      this.held.add(action);
      this.edge.add(action);
    });
    window.addEventListener('keyup', (e) => {
      const action = KEYMAP[e.code];
      if (!action) return;
      this.keys.delete(e.code);
      // don't clear a held action still provided by another key/gamepad
      const still = [...this.keys].some((code) => KEYMAP[code] === action);
      if (!still) this.held.delete(action);
    });
    window.addEventListener('blur', () => {
      this.keys.clear();
      this.held.clear();
      this.stick.active = false;
      this.stick.x = this.stick.y = 0;
    });
  }

  _bindGamepad() {
    const DEAD = 0.18;
    this.pollGamepad = () => {
      const pads = navigator.getGamepads ? navigator.getGamepads() : [];
      let gp = null;
      for (const p of pads) if (p && p.connected) { gp = p; break; }
      if (!gp) {
        if (this.pad.connected) {
          this.pad.connected = false;
          document.dispatchEvent(new CustomEvent('padchange', { detail: { connected: false } }));
        }
        this.pad.moveX = this.pad.moveY = this.pad.lookX = this.pad.lookY = 0;
        return;
      }
      if (!this.pad.connected) {
        this.pad.connected = true;
        this.pad.name = gp.id.replace(/\(.*?\)/g, '').trim().slice(0, 28);
        document.dispatchEvent(new CustomEvent('padchange', { detail: { connected: true, name: this.pad.name } }));
      }
      const ax = gp.axes;
      const lx = Math.abs(ax[0] || 0) > DEAD ? ax[0] : 0;
      const ly = Math.abs(ax[1] || 0) > DEAD ? ax[1] : 0;
      const rx = Math.abs(ax[2] || 0) > DEAD ? ax[2] : 0;
      const ry = Math.abs(ax[3] || 0) > DEAD ? ax[3] : 0;
      this.pad.moveX = lx;
      this.pad.moveY = ly;
      this.pad.lookX = rx;
      this.pad.lookY = ry;

      const b = gp.buttons;
      const down = (i) => !!(b[i] && (b[i].pressed || b[i].value > 0.5));
      const prev = this.pad.prev;
      const edgeIf = (i, name) => {
        if (down(i) && !prev[i]) this.edge.add(name);
      };
      edgeIf(0, 'action');
      edgeIf(1, 'back');
      edgeIf(2, 'action2');
      edgeIf(3, 'action2');
      edgeIf(9, 'pause');
      edgeIf(8, 'mute');
      edgeIf(12, 'up');
      edgeIf(13, 'down');
      edgeIf(14, 'left');
      edgeIf(15, 'right');

      const mapHeld = (name, on) => { if (on) this.held.add(name); else if (![...this.keys].some((code) => KEYMAP[code] === name)) this.held.delete(name); };
      mapHeld('up', down(12) || ly < -0.5);
      mapHeld('down', down(13) || ly > 0.5);
      mapHeld('left', down(14) || lx < -0.5);
      mapHeld('right', down(15) || lx > 0.5);
      mapHeld('action', down(0));
      mapHeld('action2', down(2) || down(3));
      mapHeld('sprint', down(10) || down(11));

      this.pad.prev = b.map((x) => x.pressed || x.value > 0.5);
    };
  }

  _bindTouch() {
    const stick = document.getElementById('mobileStick');
    const knob = stick?.querySelector('.stick-knob');
    const look = document.getElementById('mobileLook');
    const interact = document.getElementById('mobileInteract');

    if (stick) {
      let id = null;
      const rectCenter = () => {
        const r = stick.getBoundingClientRect();
        return { x: r.left + r.width / 2, y: r.top + r.height / 2, r: r.width * 0.36 };
      };
      const move = (e) => {
        if (id !== e.pointerId) return;
        const c = rectCenter();
        let dx = (e.clientX - c.x) / c.r;
        let dy = (e.clientY - c.y) / c.r;
        const len = Math.hypot(dx, dy);
        if (len > 1) { dx /= len; dy /= len; }
        this.stick.x = dx;
        this.stick.y = dy;
        this.stick.active = true;
        if (knob) knob.style.transform = `translate(${dx * 34}px, ${dy * 34}px)`;
      };
      const end = (e) => {
        if (id !== e.pointerId) return;
        id = null;
        this.stick.x = this.stick.y = 0;
        this.stick.active = false;
        if (knob) knob.style.transform = 'translate(0, 0)';
      };
      stick.addEventListener('pointerdown', (e) => {
        e.preventDefault();
        id = e.pointerId;
        stick.setPointerCapture(e.pointerId);
        move(e);
      });
      stick.addEventListener('pointermove', move);
      stick.addEventListener('pointerup', end);
      stick.addEventListener('pointercancel', end);
    }

    if (look) {
      let id = null, lx = 0, ly = 0;
      look.addEventListener('pointerdown', (e) => {
        id = e.pointerId;
        lx = e.clientX; ly = e.clientY;
        look.setPointerCapture(e.pointerId);
      });
      look.addEventListener('pointermove', (e) => {
        if (id !== e.pointerId) return;
        this.touchLookDX += e.clientX - lx;
        this.touchLookDY += e.clientY - ly;
        lx = e.clientX; ly = e.clientY;
      });
      const end = (e) => { if (id === e.pointerId) id = null; };
      look.addEventListener('pointerup', end);
      look.addEventListener('pointercancel', end);
    }

    if (interact) {
      interact.addEventListener('pointerdown', (e) => {
        e.preventDefault();
        this.edge.add('interact');
      });
    }

    document.querySelectorAll('[data-nav]').forEach((btn) => {
      const dir = btn.dataset.nav;
      const press = (e) => {
        e.preventDefault();
        this.held.add(dir);
        this.edge.add(dir);
        btn.classList.add('active');
      };
      const release = (e) => {
        e.preventDefault();
        this.held.delete(dir);
        btn.classList.remove('active');
      };
      btn.addEventListener('pointerdown', press);
      btn.addEventListener('pointerup', release);
      btn.addEventListener('pointercancel', release);
      btn.addEventListener('pointerleave', release);
    });
    document.querySelectorAll('[data-act]').forEach((btn) => {
      const act = btn.dataset.act;
      const press = (e) => {
        e.preventDefault();
        this.held.add(act);
        this.edge.add(act);
      };
      const release = (e) => {
        e.preventDefault();
        this.held.delete(act);
      };
      btn.addEventListener('pointerdown', press);
      btn.addEventListener('pointerup', release);
      btn.addEventListener('pointercancel', release);
      btn.addEventListener('pointerleave', release);
    });
  }

  update(dt) {
    this.pollGamepad();
    let x = 0, y = 0;
    if (this.held.has('left')) x -= 1;
    if (this.held.has('right')) x += 1;
    if (this.held.has('up')) y -= 1;
    if (this.held.has('down')) y += 1;
    if (this.stick.active) { x += this.stick.x; y += this.stick.y; }
    if (this.pad.connected) { x += this.pad.moveX; y += this.pad.moveY; }
    const len = Math.hypot(x, y);
    if (len > 1) { x /= len; y /= len; }
    this.axis.x = clamp(x, -1, 1);
    this.axis.y = clamp(y, -1, 1);
  }

  pressed(name) { return this.edge.has(name); }
  down(name) { return this.held.has(name); }
  clearEdges() {
    this.edge.clear();
    this.tv.downEdge = false;
    this.touchLookDX = 0;
    this.touchLookDY = 0;
  }
}

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.muted = false;
    this.ambient = null;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.55;
    this.master.connect(this.ctx.destination);
    this._ambient();
  }

  _ambient() {
    const ctx = this.ctx;
    const g = ctx.createGain();
    g.gain.value = 0.0;
    g.connect(this.master);
    g.gain.linearRampToValueAtTime(0.05, ctx.currentTime + 3);

    const o1 = ctx.createOscillator();
    o1.type = 'sine';
    o1.frequency.value = 55;
    const o2 = ctx.createOscillator();
    o2.type = 'sine';
    o2.frequency.value = 82.6;
    const og = ctx.createGain();
    og.gain.value = 0.32;
    o1.connect(og); o2.connect(og); og.connect(g);

    const lfo = ctx.createOscillator();
    lfo.frequency.value = 0.07;
    const lg = ctx.createGain();
    lg.gain.value = 0.12;
    lfo.connect(lg); lg.connect(og.gain);

    // airy room tone
    const len = ctx.sampleRate * 4;
    const buf = ctx.createBuffer(1, len, ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = (Math.random() * 2 - 1) * 0.5;
    const noise = ctx.createBufferSource();
    noise.buffer = buf;
    noise.loop = true;
    const nf = ctx.createBiquadFilter();
    nf.type = 'lowpass';
    nf.frequency.value = 420;
    const ng = ctx.createGain();
    ng.gain.value = 0.07;
    noise.connect(nf); nf.connect(ng); ng.connect(g);

    o1.start(); o2.start(); lfo.start(); noise.start();
    this.ambient = { g, o1, o2, lfo, noise };
  }

  setMuted(muted) {
    this.muted = muted;
    if (this.master) {
      const t = this.ctx.currentTime;
      this.master.gain.cancelScheduledValues(t);
      this.master.gain.linearRampToValueAtTime(muted ? 0 : 0.55, t + 0.2);
    }
  }

  _env(dur, gain, attack = 0.008) {
    const ctx = this.ctx;
    const g = ctx.createGain();
    const t = ctx.currentTime;
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), t + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    g.connect(this.master);
    return g;
  }

  tone(freq, dur = 0.12, { type = 'sine', gain = 0.18, slide = null, delay = 0 } = {}) {
    if (!this.ctx) return;
    const ctx = this.ctx;
    const t = ctx.currentTime + delay;
    const o = ctx.createOscillator();
    const g = this._env(dur + delay, gain);
    o.type = type;
    o.frequency.setValueAtTime(freq, t);
    if (slide) o.frequency.exponentialRampToValueAtTime(slide, t + dur);
    o.connect(g);
    o.start(t);
    o.stop(t + dur + 0.05);
  }

  noise(dur = 0.2, { gain = 0.1, freq = 1200, q = 0.8, delay = 0 } = {}) {
    if (!this.ctx) return;
    const ctx = this.ctx;
    const t = ctx.currentTime + delay;
    const len = Math.max(1, Math.floor(ctx.sampleRate * dur));
    const buf = ctx.createBuffer(1, len, ctx.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
    const src = ctx.createBufferSource();
    src.buffer = buf;
    const f = ctx.createBiquadFilter();
    f.type = 'bandpass';
    f.frequency.value = freq;
    f.Q.value = q;
    const g = this._env(dur + delay, gain, 0.004);
    src.connect(f); f.connect(g);
    src.start(t);
  }

  hover() { this.tone(1180, 0.035, { type: 'sine', gain: 0.035 }); }
  click() {
    this.tone(660, 0.06, { type: 'triangle', gain: 0.09, slide: 880 });
    this.tone(1320, 0.04, { type: 'sine', gain: 0.03, delay: 0.02 });
  }
  back() {
    this.tone(520, 0.1, { type: 'triangle', gain: 0.08, slide: 340 });
  }
  error() {
    this.tone(180, 0.18, { type: 'square', gain: 0.05, slide: 120 });
  }
  boot() {
    const notes = [174.6, 261.6, 349.2, 523.2, 698.5];
    notes.forEach((f, i) => this.tone(f, 1.4 - i * 0.08, { type: 'sine', gain: 0.09 - i * 0.008, delay: i * 0.11 }));
    this.tone(87.3, 2.4, { type: 'sine', gain: 0.06 });
    this.noise(1.2, { gain: 0.03, freq: 3000, q: 0.4 });
  }
  launch() {
    this.tone(220, 0.5, { type: 'sawtooth', gain: 0.045, slide: 880 });
    this.noise(0.45, { gain: 0.05, freq: 900 });
    [523.2, 659.2, 783.9].forEach((f, i) => this.tone(f, 0.7, { type: 'sine', gain: 0.06, delay: 0.08 + i * 0.06 }));
  }
  powerDown() {
    this.tone(420, 0.55, { type: 'sine', gain: 0.08, slide: 70 });
    this.noise(0.5, { gain: 0.04, freq: 500 });
  }
  coin() {
    this.tone(1046, 0.08, { type: 'square', gain: 0.035 });
    this.tone(1568, 0.12, { type: 'square', gain: 0.03, delay: 0.06 });
  }
  hit() {
    this.noise(0.15, { gain: 0.06, freq: 260, q: 0.6 });
    this.tone(120, 0.16, { type: 'sine', gain: 0.08, slide: 60 });
  }
}

export { clamp, rand, pick, TAU } from '../util.js';

export const W = 1280;
export const H = 720;

export function rr(ctx, x, y, w, h, r) {
  const rr2 = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + rr2, y);
  ctx.arcTo(x + w, y, x + w, y + h, rr2);
  ctx.arcTo(x + w, y + h, x, y + h, rr2);
  ctx.arcTo(x, y + h, x, y, rr2);
  ctx.arcTo(x, y, x + w, y, rr2);
  ctx.closePath();
}

export function glowText(ctx, text, x, y, size, color, { align = 'left', weight = 700, family = '"Space Grotesk", sans-serif', blur = 18 } = {}) {
  ctx.save();
  ctx.font = `${weight} ${size}px ${family}`;
  ctx.textAlign = align;
  ctx.textBaseline = 'alphabetic';
  ctx.shadowColor = color;
  ctx.shadowBlur = blur;
  ctx.fillStyle = color;
  ctx.fillText(text, x, y);
  ctx.shadowBlur = 0;
  ctx.fillStyle = '#ffffff';
  ctx.globalAlpha = 0.9;
  ctx.fillText(text, x, y);
  ctx.restore();
}

export function scanlines(ctx, w, h, alpha = 0.05) {
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.fillStyle = '#000';
  for (let y = 0; y < h; y += 3) ctx.fillRect(0, y, w, 1);
  ctx.restore();
}

export function vignette(ctx, w, h, strength = 0.5) {
  const g = ctx.createRadialGradient(w / 2, h / 2, h * 0.25, w / 2, h / 2, h * 0.85);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(1, `rgba(0,0,0,${strength})`);
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, w, h);
}

export class Particles {
  constructor() { this.list = []; }
  burst(x, y, color, count = 14, speed = 260, life = 0.7, size = 3) {
    for (let i = 0; i < count; i++) {
      const a = Math.random() * Math.PI * 2;
      const s = speed * (0.25 + Math.random() * 0.9);
      this.list.push({
        x, y,
        vx: Math.cos(a) * s,
        vy: Math.sin(a) * s,
        life: life * (0.5 + Math.random() * 0.8),
        max: life,
        color,
        size: size * (0.5 + Math.random()),
      });
    }
  }
  update(dt, gravity = 0, drag = 1.6) {
    for (let i = this.list.length - 1; i >= 0; i--) {
      const p = this.list[i];
      p.life -= dt;
      if (p.life <= 0) { this.list.splice(i, 1); continue; }
      p.vy += gravity * dt;
      p.vx *= 1 - drag * dt;
      p.vy *= 1 - drag * dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
    }
  }
  draw(ctx) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (const p of this.list) {
      const a = Math.max(0, p.life / p.max);
      ctx.globalAlpha = a;
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size * (0.4 + a * 0.6), 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.restore();
  }
}

export function drawStars(ctx, stars, w, h, camX = 0, camY = 0) {
  ctx.save();
  for (const s of stars) {
    ctx.globalAlpha = s.a;
    ctx.fillStyle = s.c;
    ctx.fillRect(((s.x - camX * s.p) % w + w) % w, ((s.y - camY * s.p) % h + h) % h, s.s, s.s);
  }
  ctx.restore();
}

export function makeStars(count = 140, w = W, h = H) {
  const colors = ['#ffffff', '#cfe0ff', '#9fc4ff', '#ffe6c0'];
  return Array.from({ length: count }, () => ({
    x: Math.random() * w,
    y: Math.random() * h,
    s: Math.random() > 0.9 ? 2.2 : 1.2,
    a: 0.25 + Math.random() * 0.7,
    p: 0.04 + Math.random() * 0.3,
    c: colors[(Math.random() * colors.length) | 0],
  }));
}

export function roundRectPath(ctx, x, y, w, h, r) {
  rr(ctx, x, y, w, h, r);
}

import { clamp, rand, TAU } from '../util.js';
import { W, H, rr, Particles, makeStars, drawStars, glowText, scanlines, vignette } from './common.js';

class Astro {
  constructor(audio) {
    this.audio = audio;
    this.reset();
  }

  reset() {
    this.platforms = [{ x: -260, w: 820, y: 592 }];
    this.nextX = 560;
    this.bolts = [];
    this.drones = [];
    this.particles = new Particles();
    this.player = { x: 150, y: 592, vx: 0, vy: 0, onGround: true, face: 1, anim: 0 };
    this.camX = 0;
    this.score = 0;
    this.boltsCollected = 0;
    this.lives = 3;
    this.state = 'playing';
    this.overTitle = 'SIGNAL LOST';
    this.overSub = 'The little astro bot ran out of juice.';
    this.time = 0;
    this.lastSafe = this.platforms[0];
    this.shake = 0;
    this.stars = makeStars(150);
    this.genAhead();
  }

  genAhead() {
    while (this.nextX < this.camX + W + 1100) this.addPlatform();
  }

  addPlatform() {
    const prev = this.platforms[this.platforms.length - 1];
    const gap = rand(70, 170);
    const w = rand(190, 360);
    const y = clamp(prev.y + rand(-85, 55), 350, 612);
    const p = { x: prev.x + prev.w + gap, w, y };
    this.platforms.push(p);
    const n = 1 + ((Math.random() * 3) | 0);
    for (let i = 0; i < n; i++) {
      this.bolts.push({
        x: p.x + (w * (i + 1)) / (n + 1),
        y: p.y - 60 - rand(0, 70),
        got: false,
        phase: rand(0, TAU),
      });
    }
    if (Math.random() < 0.34 && this.platforms.length > 2) {
      this.drones.push({
        x: p.x + w * rand(0.25, 0.75),
        baseY: p.y - 90 - rand(0, 40),
        y: 0,
        phase: rand(0, TAU),
        dead: false,
      });
    }
    this.nextX = p.x + p.w;
  }

  loseLife() {
    if (this.state !== 'playing') return;
    this.lives--;
    this.shake = 14;
    this.audio.hit();
    this.particles.burst(this.player.x, this.player.y - 18, '#ff6b8b', 26, 320, 0.8, 4);
    if (this.lives <= 0) {
      this.state = 'over';
      return;
    }
    const safe = this.lastSafe || this.platforms[0];
    this.player.x = safe.x + safe.w * 0.5;
    this.player.y = safe.y;
    this.player.vx = 0;
    this.player.vy = 0;
    this.player.onGround = true;
  }

  update(dt, input) {
    this.time += dt;
    this.shake = Math.max(0, this.shake - dt * 40);
    this.particles.update(dt, 900, 1.2);
    if (this.state !== 'playing') return;

    const p = this.player;
    const ax = input.axis.x;
    if (ax) p.face = ax > 0 ? 1 : -1;
    p.vx += (ax * 370 - p.vx) * Math.min(1, dt * 11);
    if (Math.abs(ax) < 0.05) p.vx *= 1 - dt * 4;

    if ((input.pressed('action') || input.pressed('up')) && p.onGround) {
      p.vy = -900;
      p.onGround = false;
      this.audio.tone(320, 0.12, { type: 'square', gain: 0.03, slide: 620 });
      this.particles.burst(p.x, p.y, '#7fe3ff', 10, 130, 0.4, 2.5);
    }
    p.vy += 2350 * dt;
    p.x += p.vx * dt;
    const prevY = p.y;
    p.y += p.vy * dt;

    p.onGround = false;
    for (const plat of this.platforms) {
      if (p.x > plat.x - 8 && p.x < plat.x + plat.w + 8) {
        if (p.vy >= 0 && prevY <= plat.y + 2 && p.y >= plat.y) {
          p.y = plat.y;
          p.vy = 0;
          p.onGround = true;
          this.lastSafe = plat;
          break;
        }
      }
    }
    if (p.onGround) {
      p.anim += Math.abs(p.vx) * dt * 0.05;
    } else {
      p.anim += dt * 8;
      if (Math.random() < dt * 30) {
        this.particles.list.push({
          x: p.x + rand(-6, 6), y: p.y - 6, vx: rand(-30, 30), vy: rand(30, 120),
          life: 0.35, max: 0.35, color: '#5fd8ff', size: 2,
        });
      }
    }

    if (p.y > 860) this.loseLife();

    // bolts
    for (const b of this.bolts) {
      if (b.got) continue;
      const bob = Math.sin(this.time * 3 + b.phase) * 6;
      if (Math.hypot(p.x - b.x, p.y - 24 - (b.y + bob)) < 30) {
        b.got = true;
        this.boltsCollected++;
        this.score += 50;
        this.audio.coin();
        this.particles.burst(b.x, b.y + bob, '#ffd76a', 14, 220, 0.6, 3);
      }
    }

    // drones
    for (const d of this.drones) {
      if (d.dead) continue;
      d.y = d.baseY + Math.sin(this.time * 2.2 + d.phase) * 34;
      if (Math.hypot(p.x - d.x, p.y - 22 - d.y) < 30) {
        d.dead = true;
        this.particles.burst(d.x, d.y, '#ff7d9c', 22, 260, 0.7, 3.5);
        this.loseLife();
      }
    }

    this.camX += (p.x - 370 - this.camX) * Math.min(1, dt * 5);
    this.genAhead();

    // cleanup
    const cutoff = this.camX - 400;
    if (this.platforms.length > 8) this.platforms = this.platforms.filter((pl) => pl.x + pl.w > cutoff);
    this.bolts = this.bolts.filter((b) => !b.got && b.x > cutoff);
    this.drones = this.drones.filter((d) => !d.dead && d.x > cutoff);

    this.score += dt * 10;
  }

  draw(ctx) {
    const shx = this.shake ? rand(-this.shake, this.shake) : 0;
    const shy = this.shake ? rand(-this.shake, this.shake) : 0;
    ctx.save();
    ctx.translate(shx, shy);

    // sky
    const sky = ctx.createLinearGradient(0, 0, 0, H);
    sky.addColorStop(0, '#050a1a');
    sky.addColorStop(0.45, '#0a1633');
    sky.addColorStop(0.78, '#172a4e');
    sky.addColorStop(1, '#0a1020');
    ctx.fillStyle = sky;
    ctx.fillRect(0, 0, W, H);
    drawStars(ctx, this.stars, W, H, this.camX * 0.06, 0);

    // planet
    const px = 980 - this.camX * 0.03;
    const py = 170;
    const pg = ctx.createRadialGradient(px - 30, py - 30, 10, px, py, 130);
    pg.addColorStop(0, '#9fd0ff');
    pg.addColorStop(0.4, '#3b6fd6');
    pg.addColorStop(1, '#0a1a3a');
    ctx.fillStyle = pg;
    ctx.beginPath(); ctx.arc(px, py, 120, 0, TAU); ctx.fill();
    ctx.save();
    ctx.translate(px, py);
    ctx.rotate(-0.35);
    ctx.strokeStyle = 'rgba(130,190,255,0.45)';
    ctx.lineWidth = 9;
    ctx.beginPath(); ctx.ellipse(0, 0, 180, 42, 0, 0, TAU); ctx.stroke();
    ctx.restore();

    // distant skyline
    const skyline = (offset, color, base, scale) => {
      ctx.fillStyle = color;
      const start = -((this.camX * offset) % 320) - 320;
      for (let x = start; x < W + 320; x += 320) {
        for (let i = 0; i < 8; i++) {
          const bw = 34 + ((i * 37) % 54);
          const bh = (60 + ((i * 53) % 130)) * scale;
          ctx.fillRect(x + i * 40, base - bh, bw, bh);
        }
      }
    };
    skyline(0.1, 'rgba(16,28,54,0.8)', 600, 1.2);
    skyline(0.22, 'rgba(8,16,32,0.9)', 660, 1);

    ctx.save();
    ctx.translate(-this.camX, 0);

    // platforms
    for (const plat of this.platforms) {
      if (plat.x + plat.w < this.camX - 100 || plat.x > this.camX + W + 100) continue;
      const g = ctx.createLinearGradient(0, plat.y, 0, plat.y + 70);
      g.addColorStop(0, '#1a2947');
      g.addColorStop(1, '#070c17');
      ctx.fillStyle = g;
      rr(ctx, plat.x, plat.y, plat.w, 54, 10);
      ctx.fill();
      ctx.strokeStyle = 'rgba(90,140,230,0.25)';
      ctx.lineWidth = 1;
      ctx.stroke();
      ctx.save();
      ctx.shadowColor = '#5fd8ff';
      ctx.shadowBlur = 18;
      ctx.strokeStyle = '#6fe3ff';
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.moveTo(plat.x + 6, plat.y + 1.5);
      ctx.lineTo(plat.x + plat.w - 6, plat.y + 1.5);
      ctx.stroke();
      ctx.restore();
      // support struts
      ctx.strokeStyle = 'rgba(80,120,190,0.12)';
      for (let sx = plat.x + 30; sx < plat.x + plat.w - 20; sx += 60) {
        ctx.beginPath();
        ctx.moveTo(sx, plat.y + 40);
        ctx.lineTo(sx + 20, plat.y + 120);
        ctx.stroke();
      }
    }

    // bolts
    for (const b of this.bolts) {
      if (b.got) continue;
      const bob = Math.sin(this.time * 3 + b.phase) * 6;
      ctx.save();
      ctx.translate(b.x, b.y + bob);
      ctx.rotate(this.time * 2 + b.phase);
      ctx.shadowColor = '#ffd76a';
      ctx.shadowBlur = 20;
      ctx.fillStyle = '#ffd76a';
      ctx.beginPath();
      ctx.moveTo(0, -12); ctx.lineTo(9, 0); ctx.lineTo(0, 12); ctx.lineTo(-9, 0);
      ctx.closePath();
      ctx.fill();
      ctx.fillStyle = '#fff6cf';
      ctx.beginPath(); ctx.arc(0, 0, 3.5, 0, TAU); ctx.fill();
      ctx.restore();
    }

    // drones
    for (const d of this.drones) {
      if (d.dead) continue;
      const y = d.baseY + Math.sin(this.time * 2.2 + d.phase) * 34;
      ctx.save();
      ctx.translate(d.x, y);
      ctx.shadowColor = '#ff5f8a';
      ctx.shadowBlur = 22;
      ctx.fillStyle = '#ff5f8a';
      ctx.beginPath();
      ctx.moveTo(0, -16); ctx.lineTo(18, 0); ctx.lineTo(0, 16); ctx.lineTo(-18, 0);
      ctx.closePath();
      ctx.fill();
      ctx.shadowBlur = 0;
      ctx.fillStyle = '#1a0a12';
      ctx.beginPath(); ctx.arc(0, 0, 7, 0, TAU); ctx.fill();
      ctx.fillStyle = '#ffd0dd';
      ctx.beginPath(); ctx.arc(0, 0, 3, 0, TAU); ctx.fill();
      // rotor
      ctx.strokeStyle = 'rgba(255,150,180,0.5)';
      ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(-24, -14); ctx.lineTo(24, -14); ctx.stroke();
      ctx.restore();
    }

    // player
    this.drawBot(ctx);

    this.particles.draw(ctx);
    ctx.restore();

    vignette(ctx, W, H, 0.45);
    scanlines(ctx, W, H, 0.035);

    // HUD
    ctx.save();
    ctx.font = '700 11px "Inter", sans-serif';
    ctx.fillStyle = 'rgba(150,180,235,0.6)';
    ctx.letterSpacing = '4px';
    ctx.fillText('SCORE', 54, 62);
    glowText(ctx, String(Math.floor(this.score)).padStart(7, '0'), 54, 104, 34, '#dff1ff', { blur: 14 });
    ctx.fillStyle = 'rgba(150,180,235,0.6)';
    ctx.letterSpacing = '4px';
    ctx.fillText('BOLTS', 260, 62);
    glowText(ctx, String(this.boltsCollected).padStart(2, '0'), 260, 104, 34, '#ffd76a', { blur: 14 });
    // lives
    for (let i = 0; i < 3; i++) {
      ctx.globalAlpha = i < this.lives ? 1 : 0.18;
      ctx.fillStyle = i < this.lives ? '#6fe3ff' : '#5a6a86';
      ctx.beginPath();
      ctx.arc(W - 66 - i * 30, 82, 8, 0, TAU);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
    ctx.textAlign = 'right';
    ctx.font = '600 10px "Inter", sans-serif';
    ctx.fillStyle = 'rgba(160,185,235,0.55)';
    ctx.fillText('LIVES', W - 60, 112);
    ctx.restore();
  }

  drawBot(ctx) {
    const p = this.player;
    const bob = p.onGround ? Math.sin(p.anim * 2) * 1.5 : 0;
    ctx.save();
    ctx.translate(p.x, p.y + bob);
    ctx.scale(p.face, 1);
    if (!p.onGround) {
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      const fl = ctx.createLinearGradient(0, -6, 0, 26);
      fl.addColorStop(0, 'rgba(120,220,255,0.9)');
      fl.addColorStop(1, 'rgba(80,140,255,0)');
      ctx.fillStyle = fl;
      ctx.beginPath();
      ctx.moveTo(-7, -4); ctx.lineTo(7, -4); ctx.lineTo(0, 26); ctx.closePath();
      ctx.fill();
      ctx.restore();
    }
    // legs
    ctx.strokeStyle = '#c9d6ee';
    ctx.lineWidth = 4;
    ctx.lineCap = 'round';
    const stride = p.onGround ? Math.sin(p.anim * 2) * 5 : 3;
    ctx.beginPath(); ctx.moveTo(-5, -7); ctx.lineTo(-5 - stride, 0); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(5, -7); ctx.lineTo(5 + stride, 0); ctx.stroke();
    // body
    ctx.shadowColor = '#5fd8ff';
    ctx.shadowBlur = 22;
    const bg = ctx.createLinearGradient(0, -40, 0, 0);
    bg.addColorStop(0, '#ffffff');
    bg.addColorStop(1, '#b9cbe8');
    ctx.fillStyle = bg;
    rr(ctx, -14, -40, 28, 34, 12);
    ctx.fill();
    ctx.shadowBlur = 0;
    // visor
    ctx.fillStyle = '#0a1220';
    rr(ctx, -10, -34, 20, 15, 7);
    ctx.fill();
    ctx.fillStyle = '#6fe3ff';
    ctx.shadowColor = '#6fe3ff';
    ctx.shadowBlur = 10;
    ctx.beginPath(); ctx.arc(-4, -27, 2.2, 0, TAU); ctx.fill();
    ctx.beginPath(); ctx.arc(4, -27, 2.2, 0, TAU); ctx.fill();
    ctx.shadowBlur = 0;
    // antenna
    ctx.strokeStyle = '#c9d6ee';
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(0, -40); ctx.lineTo(0, -50); ctx.stroke();
    ctx.fillStyle = '#ffd76a';
    ctx.shadowColor = '#ffd76a';
    ctx.shadowBlur = 12;
    ctx.beginPath(); ctx.arc(0, -52, 3.5, 0, TAU); ctx.fill();
    ctx.shadowBlur = 0;
    // arm
    ctx.strokeStyle = '#c9d6ee';
    ctx.lineWidth = 4;
    ctx.beginPath(); ctx.moveTo(12, -26); ctx.lineTo(18, -16 + (p.onGround ? Math.sin(p.anim * 2 + 1) * 3 : -4)); ctx.stroke();
    ctx.restore();
  }
}

