import { clamp, rand, TAU } from '../util.js';
import { W, H, rr, Particles, makeStars, drawStars, glowText, scanlines, vignette } from './common.js';

class Starfall {
  constructor(audio) {
    this.audio = audio;
    this.reset();
  }

  reset() {
    this.player = { x: W / 2, y: H - 130, vx: 0, vy: 0, invuln: 2, fireCd: 0, tilt: 0 };
    this.bullets = [];
    this.enemyBullets = [];
    this.enemies = [];
    this.pickups = [];
    this.particles = new Particles();
    this.score = 0;
    this.lives = 3;
    this.wave = 1;
    this.time = 0;
    this.spawnTimer = 0.6;
    this.waveTimer = 0;
    this.state = 'playing';
    this.overTitle = 'SIGNAL LOST';
    this.overSub = 'The starfall swallowed your ship.';
    this.shake = 0;
    this.empCd = 0;
    this.empFx = 0;
    this.weapon = 0;
    this.weaponTimer = 0;
    this.stars = makeStars(180);
    this.stars2 = makeStars(70);
  }

  fire() {
    const p = this.player;
    const speed = -1050;
    const mk = (dx, ang = 0) => {
      this.bullets.push({ x: p.x + dx, y: p.y - 22, vx: Math.sin(ang) * 260, vy: speed, life: 2, dmg: 1 });
    };
    if (this.weapon > 0) {
      mk(-16, -0.12); mk(0, 0); mk(16, 0.12);
    } else {
      mk(-8); mk(8);
    }
    this.audio.tone(880 + Math.random() * 80, 0.04, { type: 'square', gain: 0.018 });
  }

  spawnEnemy() {
    const diff = Math.min(1, this.time / 90);
    const roll = Math.random();
    let type = 'grunt';
    if (roll > 0.82 - diff * 0.1) type = 'tank';
    else if (roll > 0.5) type = 'zig';
    const hp = type === 'tank' ? 6 : type === 'zig' ? 2 : 1;
    const radius = type === 'tank' ? 30 : 20;
    this.enemies.push({
      x: rand(70, W - 70),
      y: -50,
      type,
      hp,
      maxHp: hp,
      r: radius,
      speed: (type === 'tank' ? 42 : type === 'zig' ? 100 : 85) + diff * 40,
      phase: rand(0, TAU),
      baseX: rand(70, W - 70),
      shootCd: rand(1.2, 2.6),
      flash: 0,
    });
  }

  hitPlayer() {
    const p = this.player;
    if (p.invuln > 0) return;
    this.lives--;
    this.shake = 18;
    this.audio.hit();
    this.particles.burst(p.x, p.y, '#ff7d9c', 30, 420, 0.9, 4);
    p.invuln = 2.2;
    this.weapon = 0;
    this.weaponTimer = 0;
    if (this.lives <= 0) this.state = 'over';
  }

  update(dt, input) {
    this.time += dt;
    this.shake = Math.max(0, this.shake - dt * 45);
    this.empFx = Math.max(0, this.empFx - dt);
    this.empCd = Math.max(0, this.empCd - dt);
    this.particles.update(dt, 0, 0.8);
    if (this.state !== 'playing') return;

    const p = this.player;
    p.invuln = Math.max(0, p.invuln - dt);
    const focus = input.down('action') ? 0.55 : 1;
    const speed = 460 * focus;
    const ax = input.axis.x;
    const ay = input.axis.y;
    p.vx += (ax * speed - p.vx) * Math.min(1, dt * 12);
    p.vy += (ay * speed - p.vy) * Math.min(1, dt * 12);
    p.x = clamp(p.x + p.vx * dt, 50, W - 50);
    p.y = clamp(p.y + p.vy * dt, H * 0.38, H - 64);
    p.tilt += (p.vx / 460 - p.tilt) * Math.min(1, dt * 8);

    p.fireCd -= dt;
    if (p.fireCd <= 0) {
      this.fire();
      p.fireCd = this.weapon > 0 ? 0.085 : 0.13;
    }

    if (input.pressed('action') && this.empCd <= 0) {
      this.empCd = 5;
      this.empFx = 0.7;
      this.shake = 10;
      this.audio.tone(120, 0.5, { type: 'sine', gain: 0.09, slide: 520 });
      this.audio.noise(0.4, { gain: 0.05, freq: 1400 });
      for (const b of this.enemyBullets) this.particles.burst(b.x, b.y, '#8fe9ff', 2, 90, 0.35, 2);
      this.enemyBullets.length = 0;
      for (const e of this.enemies) {
        e.hp -= 2;
        e.flash = 0.15;
        this.particles.burst(e.x, e.y, '#8fe9ff', 6, 150, 0.4, 2);
      }
    }

    this.weaponTimer = Math.max(0, this.weaponTimer - dt);
    if (this.weaponTimer <= 0) this.weapon = 0;

    // waves
    this.spawnTimer -= dt;
    if (this.spawnTimer <= 0) {
      this.spawnTimer = Math.max(0.22, 0.8 - this.time * 0.006);
      this.spawnEnemy();
      if (this.time > 30 && Math.random() < 0.35) this.spawnEnemy();
    }
    this.waveTimer += dt;
    if (this.waveTimer > 20) {
      this.waveTimer = 0;
      this.wave++;
    }

    // player bullets
    for (let i = this.bullets.length - 1; i >= 0; i--) {
      const b = this.bullets[i];
      b.x += b.vx * dt;
      b.y += b.vy * dt;
      b.life -= dt;
      if (b.life <= 0 || b.y < -20) { this.bullets.splice(i, 1); continue; }
      for (const e of this.enemies) {
        if (e.hp > 0 && Math.hypot(b.x - e.x, b.y - e.y) < e.r + 5) {
          e.hp -= b.dmg;
          e.flash = 0.12;
          this.particles.burst(b.x, b.y, '#a8f0ff', 5, 130, 0.3, 2);
          this.bullets.splice(i, 1);
          if (e.hp <= 0) {
            this.score += e.type === 'tank' ? 150 : e.type === 'zig' ? 80 : 50;
            this.audio.tone(220, 0.16, { type: 'sawtooth', gain: 0.03, slide: 90 });
            this.particles.burst(e.x, e.y, e.type === 'tank' ? '#ffb84f' : '#ff7d9c', 24, 300, 0.7, 3.5);
            if (Math.random() < (e.type === 'tank' ? 0.55 : 0.1)) {
              this.pickups.push({ x: e.x, y: e.y, vy: 60, kind: Math.random() < 0.5 ? 'rapid' : 'shield', phase: rand(0, TAU) });
            }
          }
          break;
        }
      }
    }

    // enemies
    for (let i = this.enemies.length - 1; i >= 0; i--) {
      const e = this.enemies[i];
      if (e.hp <= 0) { this.enemies.splice(i, 1); continue; }
      e.flash = Math.max(0, e.flash - dt);
      if (e.type === 'zig') {
        e.phase += dt * 2.2;
        e.x = e.baseX + Math.sin(e.phase) * 130;
        e.y += e.speed * dt * 0.75;
      } else {
        e.y += e.speed * dt;
      }
      e.x = clamp(e.x, 40, W - 40);
      if (e.y > H + 60) { this.enemies.splice(i, 1); continue; }
      if (e.y > 0 && e.y < H * 0.7) {
        e.shootCd -= dt;
        if (e.shootCd <= 0) {
          e.shootCd = rand(1.4, 2.8);
          const ang = Math.atan2(p.y - e.y, p.x - e.x);
          const sp = 250 + Math.min(160, this.time * 2);
          this.enemyBullets.push({ x: e.x, y: e.y + e.r * 0.6, vx: Math.cos(ang) * sp, vy: Math.sin(ang) * sp, life: 5 });
        }
      }
      if (Math.hypot(p.x - e.x, p.y - e.y) < e.r + 16) {
        e.hp = 0;
        this.particles.burst(e.x, e.y, '#ffb84f', 18, 260, 0.6, 3);
        this.hitPlayer();
      }
    }

    // enemy bullets
    for (let i = this.enemyBullets.length - 1; i >= 0; i--) {
      const b = this.enemyBullets[i];
      b.x += b.vx * dt;
      b.y += b.vy * dt;
      b.life -= dt;
      if (b.life <= 0 || b.y > H + 20 || b.x < -20 || b.x > W + 20) { this.enemyBullets.splice(i, 1); continue; }
      if (Math.hypot(p.x - b.x, p.y - b.y) < 17) {
        this.enemyBullets.splice(i, 1);
        this.hitPlayer();
      }
    }

    // pickups
    for (let i = this.pickups.length - 1; i >= 0; i--) {
      const pk = this.pickups[i];
      pk.y += pk.vy * dt;
      pk.phase += dt * 4;
      if (pk.y > H + 20) { this.pickups.splice(i, 1); continue; }
      if (Math.hypot(p.x - pk.x, p.y - pk.y) < 30) {
        this.pickups.splice(i, 1);
        if (pk.kind === 'rapid') { this.weapon = 1; this.weaponTimer = 12; }
        else { p.invuln = Math.max(p.invuln, 4.5); }
        this.audio.coin();
        this.particles.burst(pk.x, pk.y, '#8fe9ff', 16, 200, 0.5, 3);
      }
    }

    this.score += dt * 8;
  }

  drawShip(ctx, x, y, tilt) {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(tilt * 0.22);
    // engine flame
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const fl = ctx.createLinearGradient(0, 12, 0, 54);
    fl.addColorStop(0, 'rgba(120,225,255,0.9)');
    fl.addColorStop(1, 'rgba(60,120,255,0)');
    ctx.fillStyle = fl;
    ctx.beginPath(); ctx.moveTo(-8, 14); ctx.lineTo(8, 14); ctx.lineTo(0, 54); ctx.closePath(); ctx.fill();
    ctx.restore();
    // wings
    ctx.shadowColor = '#5fd8ff';
    ctx.shadowBlur = 20;
    ctx.fillStyle = '#cfe3ff';
    ctx.beginPath();
    ctx.moveTo(0, -30);
    ctx.lineTo(30, 18);
    ctx.lineTo(10, 12);
    ctx.lineTo(0, 20);
    ctx.lineTo(-10, 12);
    ctx.lineTo(-30, 18);
    ctx.closePath();
    ctx.fill();
    ctx.shadowBlur = 0;
    ctx.fillStyle = '#23375c';
    ctx.beginPath();
    ctx.moveTo(0, -22);
    ctx.lineTo(13, 10);
    ctx.lineTo(0, 6);
    ctx.lineTo(-13, 10);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = '#6fe3ff';
    ctx.shadowColor = '#6fe3ff';
    ctx.shadowBlur = 16;
    ctx.beginPath(); ctx.arc(0, -6, 5, 0, TAU); ctx.fill();
    ctx.restore();
  }

  draw(ctx) {
    const shx = this.shake ? rand(-this.shake, this.shake) : 0;
    const shy = this.shake ? rand(-this.shake, this.shake) : 0;
    ctx.save();
    ctx.translate(shx, shy);

    const bg = ctx.createLinearGradient(0, 0, 0, H);
    bg.addColorStop(0, '#03060f');
    bg.addColorStop(0.5, '#071027');
    bg.addColorStop(1, '#040711');
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, W, H);
    const neb = ctx.createRadialGradient(W * 0.22, H * 0.28, 10, W * 0.22, H * 0.28, 420);
    neb.addColorStop(0, 'rgba(60,120,220,0.22)');
    neb.addColorStop(1, 'rgba(60,120,220,0)');
    ctx.fillStyle = neb;
    ctx.fillRect(0, 0, W, H);
    const neb2 = ctx.createRadialGradient(W * 0.78, H * 0.62, 10, W * 0.78, H * 0.62, 380);
    neb2.addColorStop(0, 'rgba(190,60,150,0.14)');
    neb2.addColorStop(1, 'rgba(190,60,150,0)');
    ctx.fillStyle = neb2;
    ctx.fillRect(0, 0, W, H);
    drawStars(ctx, this.stars, W, H, 0, -this.time * 18);
    drawStars(ctx, this.stars2, W, H, 0, -this.time * 50);

    // grid
    ctx.save();
    ctx.strokeStyle = 'rgba(80,140,230,0.07)';
    ctx.lineWidth = 1;
    for (let x = 0; x < W; x += 64) { ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, H); ctx.stroke(); }
    for (let y = (this.time * 20) % 64; y < H; y += 64) { ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(W, y); ctx.stroke(); }
    ctx.restore();

    // pickups
    for (const pk of this.pickups) {
      ctx.save();
      ctx.translate(pk.x, pk.y + Math.sin(pk.phase) * 4);
      ctx.rotate(pk.phase * 0.5);
      ctx.shadowColor = '#6fe3ff';
      ctx.shadowBlur = 18;
      ctx.strokeStyle = '#6fe3ff';
      ctx.lineWidth = 2;
      ctx.strokeRect(-10, -10, 20, 20);
      ctx.fillStyle = pk.kind === 'rapid' ? '#ffd76a' : '#6fe3ff';
      ctx.font = '700 12px "Inter", sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(pk.kind === 'rapid' ? 'R' : 'S', 0, 4);
      ctx.restore();
    }

    // enemies
    for (const e of this.enemies) {
      ctx.save();
      ctx.translate(e.x, e.y);
      const col = e.type === 'tank' ? '#ffb84f' : e.type === 'zig' ? '#c78bff' : '#ff6b8b';
      ctx.shadowColor = col;
      ctx.shadowBlur = 18;
      ctx.fillStyle = e.flash > 0 ? '#ffffff' : col;
      ctx.beginPath();
      if (e.type === 'tank') {
        ctx.moveTo(0, e.r); ctx.lineTo(e.r, 0); ctx.lineTo(e.r * 0.6, -e.r * 0.8);
        ctx.lineTo(-e.r * 0.6, -e.r * 0.8); ctx.lineTo(-e.r, 0); ctx.closePath();
      } else {
        ctx.moveTo(0, e.r); ctx.lineTo(e.r * 0.9, -e.r * 0.7); ctx.lineTo(0, -e.r * 0.2);
        ctx.lineTo(-e.r * 0.9, -e.r * 0.7); ctx.closePath();
      }
      ctx.fill();
      ctx.shadowBlur = 0;
      ctx.fillStyle = '#120612';
      ctx.beginPath(); ctx.arc(0, e.type === 'tank' ? 0 : 2, e.r * 0.3, 0, TAU); ctx.fill();
      ctx.fillStyle = '#ffe2ec';
      ctx.beginPath(); ctx.arc(0, e.type === 'tank' ? 0 : 2, e.r * 0.12, 0, TAU); ctx.fill();
      if (e.hp < e.maxHp) {
        ctx.fillStyle = 'rgba(0,0,0,0.6)';
        ctx.fillRect(-e.r, -e.r - 12, e.r * 2, 4);
        ctx.fillStyle = col;
        ctx.fillRect(-e.r, -e.r - 12, (e.r * 2 * e.hp) / e.maxHp, 4);
      }
      ctx.restore();
    }

    // bullets
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (const b of this.bullets) {
      ctx.strokeStyle = 'rgba(140,240,255,0.9)';
      ctx.lineWidth = 3;
      ctx.shadowColor = '#6fe3ff';
      ctx.shadowBlur = 12;
      ctx.beginPath(); ctx.moveTo(b.x, b.y + 10); ctx.lineTo(b.x, b.y - 14); ctx.stroke();
    }
    for (const b of this.enemyBullets) {
      ctx.strokeStyle = 'rgba(255,130,180,0.9)';
      ctx.lineWidth = 3;
      ctx.shadowColor = '#ff5f9c';
      ctx.shadowBlur = 12;
      ctx.beginPath(); ctx.moveTo(b.x - b.vx * 0.02, b.y - b.vy * 0.02); ctx.lineTo(b.x, b.y); ctx.stroke();
    }
    ctx.restore();

    if (this.player.invuln <= 0 || Math.sin(this.time * 30) > 0) {
      this.drawShip(ctx, this.player.x, this.player.y, this.player.tilt);
    }

    // emp ring
    if (this.empFx > 0) {
      const t = 1 - this.empFx / 0.7;
      ctx.save();
      ctx.strokeStyle = `rgba(140,235,255,${1 - t})`;
      ctx.lineWidth = 6 * (1 - t) + 1;
      ctx.beginPath(); ctx.arc(this.player.x, this.player.y, t * 620, 0, TAU); ctx.stroke();
      ctx.restore();
    }

    this.particles.draw(ctx);
    ctx.restore();

    vignette(ctx, W, H, 0.55);
    scanlines(ctx, W, H, 0.035);

    // HUD
    ctx.save();
    ctx.font = '700 11px "Inter", sans-serif';
    ctx.fillStyle = 'rgba(150,190,255,0.6)';
    ctx.letterSpacing = '4px';
    ctx.fillText('SCORE', 54, 62);
    glowText(ctx, String(Math.floor(this.score)).padStart(7, '0'), 54, 102, 32, '#e6f4ff', { blur: 14 });
    ctx.fillStyle = 'rgba(150,190,255,0.6)';
    ctx.letterSpacing = '4px';
    ctx.fillText('WAVE', 262, 62);
    glowText(ctx, String(this.wave).padStart(2, '0'), 262, 102, 32, '#8fe9ff', { blur: 14 });
    // lives
    for (let i = 0; i < 3; i++) {
      ctx.globalAlpha = i < this.lives ? 1 : 0.16;
      ctx.fillStyle = '#ff7d9c';
      ctx.beginPath();
      ctx.moveTo(W - 64 - i * 28, 92);
      ctx.lineTo(W - 74 - i * 28, 74);
      ctx.lineTo(W - 84 - i * 28, 92);
      ctx.closePath(); ctx.fill();
    }
    ctx.globalAlpha = 1;
    // emp cooldown
    ctx.fillStyle = 'rgba(150,190,255,0.5)';
    ctx.font = '600 10px "Inter", sans-serif';
    ctx.textAlign = 'right';
    ctx.fillText('EMP', W - 54, 124);
    ctx.fillStyle = 'rgba(255,255,255,0.12)';
    rr(ctx, W - 132, 132, 78, 6, 3); ctx.fill();
    ctx.fillStyle = this.empCd <= 0 ? '#6fe3ff' : '#4a6fa0';
    rr(ctx, W - 132, 132, 78 * (1 - this.empCd / 5), 6, 3); ctx.fill();
    if (this.weapon > 0) {
      ctx.fillStyle = '#ffd76a';
      ctx.fillText(`RAPID ${this.weaponTimer.toFixed(1)}s`, W - 54, 158);
    }
    ctx.restore();
  }
}

export default {
  id: 'starfall',
  title: 'STARFALL',
  subtitle: 'DEEP SPACE DEFENSE',
  accent: '#8fe9ff',
  accent2: '#173f6b',
  tagline: 'Hold the line. Light up the dark.',
  drawCover(ctx, w, h) {
    const g = ctx.createLinearGradient(0, 0, 0, h);
    g.addColorStop(0, '#040b1c');
    g.addColorStop(0.6, '#0a1b3a');
    g.addColorStop(1, '#02040a');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);
    const neb = ctx.createRadialGradient(w * 0.3, h * 0.35, 4, w * 0.3, h * 0.35, w * 0.6);
    neb.addColorStop(0, 'rgba(80,180,255,0.4)');
    neb.addColorStop(1, 'rgba(20,60,140,0)');
    ctx.fillStyle = neb;
    ctx.fillRect(0, 0, w, h);
    for (let i = 0; i < 70; i++) {
      ctx.fillStyle = `rgba(220,240,255,${0.2 + Math.random() * 0.7})`;
      ctx.fillRect(Math.random() * w, Math.random() * h, Math.random() > 0.9 ? 2 : 1, 1);
    }
    // ship
    ctx.save();
    ctx.translate(w * 0.5, h * 0.55);
    ctx.scale(w / 320, w / 320);
    ctx.shadowColor = '#6fe3ff';
    ctx.shadowBlur = 30;
    ctx.fillStyle = '#d7e9ff';
    ctx.beginPath();
    ctx.moveTo(0, -110); ctx.lineTo(90, 60); ctx.lineTo(26, 34); ctx.lineTo(0, 62);
    ctx.lineTo(-26, 34); ctx.lineTo(-90, 60); ctx.closePath(); ctx.fill();
    ctx.shadowBlur = 0;
    ctx.fillStyle = '#18305a';
    ctx.beginPath();
    ctx.moveTo(0, -86); ctx.lineTo(38, 40); ctx.lineTo(0, 18); ctx.lineTo(-38, 40); ctx.closePath(); ctx.fill();
    ctx.fillStyle = '#6fe3ff';
    ctx.beginPath(); ctx.arc(0, -30, 12, 0, TAU); ctx.fill();
    ctx.restore();
    ctx.fillStyle = '#ffffff';
    ctx.font = `700 ${Math.round(w * 0.16)}px "Space Grotesk", sans-serif`;
    ctx.fillText('STAR', w * 0.07, h * 0.84);
    ctx.fillStyle = '#8fe9ff';
    ctx.fillText('FALL', w * 0.07 + w * 0.4, h * 0.84);
    ctx.fillStyle = 'rgba(170,220,255,0.65)';
    ctx.font = `600 ${Math.round(w * 0.045)}px "Inter", sans-serif`;
    ctx.fillText('DEEP SPACE DEFENSE', w * 0.07, h * 0.9);
  },
  create({ audio }) {
    return new Starfall(audio);
  },
};

import { clamp, rand, TAU } from '../util.js';
import { W, H, rr, Particles, glowText, scanlines, vignette } from './common.js';

const LEFT = 74;
const RIGHT = W - 74;
const TOP = 126;
const BOTTOM = H - 58;
const PW = 15;
const PH = 112;

class Pong {
  constructor(audio) {
    this.audio = audio;
    this.reset();
  }

  reset() {
    this.playerY = H / 2;
    this.aiY = H / 2;
    this.playerScore = 0;
    this.aiScore = 0;
    this.rally = 0;
    this.state = 'playing';
    this.overTitle = 'VICTORY';
    this.overSub = 'First to seven. The night is yours.';
    this.time = 0;
    this.serveTimer = 0.9;
    this.ball = { x: W / 2, y: H / 2, vx: 0, vy: 0, r: 10, speed: 540 };
    this.trail = [];
    this.particles = new Particles();
    this.shake = 0;
    this.aiTarget = H / 2;
    this.aiError = 0;
    this.lastHit = 0;
  }

  serve(dir = 0) {
    const angle = rand(-0.34, 0.34);
    const d = dir || (Math.random() > 0.5 ? 1 : -1);
    this.ball.x = W / 2;
    this.ball.y = H / 2 + rand(-80, 80);
    this.ball.speed = 540;
    this.ball.vx = Math.cos(angle) * this.ball.speed * d;
    this.ball.vy = Math.sin(angle) * this.ball.speed;
    this.rally = 0;
    this.trail.length = 0;
    this.serveTimer = 0;
    this.audio.tone(420, 0.12, { type: 'sine', gain: 0.05, slide: 620 });
  }

  point(playerWon) {
    if (playerWon) this.playerScore++; else this.aiScore++;
    this.audio.tone(playerWon ? 660 : 220, 0.35, { type: 'triangle', gain: 0.08, slide: playerWon ? 880 : 140 });
    this.particles.burst(this.ball.x, this.ball.y, playerWon ? '#6fe3ff' : '#ff6b8b', 26, 380, 0.8, 3.5);
    this.shake = 8;
    if (this.playerScore >= 7 || this.aiScore >= 7) {
      this.state = 'over';
      this.overTitle = this.playerScore >= 7 ? 'VICTORY' : 'DEFEAT';
      this.overSub = this.playerScore >= 7 ? 'First to seven. The night is yours.' : 'The machine takes the set. Run it back.';
      return;
    }
    this.ball.vx = 0;
    this.ball.vy = 0;
    this.ball.x = W / 2;
    this.ball.y = H / 2;
    this.serveTimer = 1.0;
  }

  update(dt, input) {
    this.time += dt;
    this.shake = Math.max(0, this.shake - dt * 40);
    this.particles.update(dt, 0, 1.4);
    if (this.state !== 'playing') return;

    // player paddle
    let target = this.playerY;
    if (input.tv.active) target = input.tv.y * H;
    else if (input.axis.y) target += input.axis.y * 780 * dt;
    this.playerY += (target - this.playerY) * Math.min(1, dt * 18);
    this.playerY = clamp(this.playerY, TOP + PH / 2, BOTTOM - PH / 2);

    // AI
    const ball = this.ball;
    if (ball.vx > 0) {
      const travel = (RIGHT - 30 - ball.x) / Math.max(1, ball.vx);
      this.aiTarget = ball.y + ball.vy * travel * 0.72;
    }
    this.aiError += (rand(-1, 1) * 30 - this.aiError) * Math.min(1, dt * 2);
    const aiSpeed = 420 + Math.min(260, this.rally * 22);
    const diff = this.aiTarget + this.aiError - this.aiY;
    this.aiY += clamp(diff, -aiSpeed * dt, aiSpeed * dt);
    this.aiY = clamp(this.aiY, TOP + PH / 2, BOTTOM - PH / 2);

    if (this.serveTimer > 0) {
      this.serveTimer -= dt;
      if (this.serveTimer <= 0) this.serve(this.lastHit === 0 ? 0 : this.lastHit);
      return;
    }

    ball.x += ball.vx * dt;
    ball.y += ball.vy * dt;

    this.trail.push({ x: ball.x, y: ball.y });
    if (this.trail.length > 14) this.trail.shift();

    if (ball.y < TOP + ball.r) {
      ball.y = TOP + ball.r;
      ball.vy = Math.abs(ball.vy);
      this.audio.tone(300, 0.05, { type: 'square', gain: 0.03 });
      this.particles.burst(ball.x, TOP, '#6fe3ff', 6, 120, 0.35, 2);
    }
    if (ball.y > BOTTOM - ball.r) {
      ball.y = BOTTOM - ball.r;
      ball.vy = -Math.abs(ball.vy);
      this.audio.tone(300, 0.05, { type: 'square', gain: 0.03 });
      this.particles.burst(ball.x, BOTTOM, '#6fe3ff', 6, 120, 0.35, 2);
    }

    const hitPaddle = (px, py) => {
      if (Math.abs(ball.y - py) > PH / 2 + ball.r) return false;
      if (Math.abs(ball.x - px) > PW / 2 + ball.r) return false;
      return true;
    };

    if (ball.vx < 0 && hitPaddle(LEFT, this.playerY)) {
      ball.x = LEFT + PW / 2 + ball.r;
      const off = clamp((ball.y - this.playerY) / (PH / 2), -1, 1);
      const angle = off * 0.85;
      ball.speed = Math.min(1150, ball.speed * 1.055);
      ball.vx = Math.cos(angle) * ball.speed;
      ball.vy = Math.sin(angle) * ball.speed;
      this.rally++;
      this.lastHit = 1;
      this.shake = 5;
      this.audio.tone(520 + this.rally * 14, 0.07, { type: 'square', gain: 0.045 });
      this.particles.burst(ball.x, ball.y, '#6fe3ff', 10, 200, 0.4, 2.5);
    }
    if (ball.vx > 0 && hitPaddle(RIGHT, this.aiY)) {
      ball.x = RIGHT - PW / 2 - ball.r;
      const off = clamp((ball.y - this.aiY) / (PH / 2), -1, 1);
      const angle = off * 0.85 + Math.PI;
      ball.speed = Math.min(1150, ball.speed * 1.055);
      ball.vx = Math.cos(angle) * ball.speed;
      ball.vy = Math.sin(angle) * ball.speed;
      this.rally++;
      this.lastHit = -1;
      this.audio.tone(440, 0.07, { type: 'square', gain: 0.04 });
      this.particles.burst(ball.x, ball.y, '#ff8fc4', 10, 200, 0.4, 2.5);
    }

    if (ball.x < LEFT - 40) this.point(false);
    else if (ball.x > RIGHT + 40) this.point(true);
  }

  draw(ctx) {
    const shx = this.shake ? rand(-this.shake, this.shake) : 0;
    ctx.save();
    ctx.translate(shx, 0);

    const bg = ctx.createLinearGradient(0, 0, 0, H);
    bg.addColorStop(0, '#050a18');
    bg.addColorStop(0.55, '#081026');
    bg.addColorStop(1, '#03060f');
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, W, H);

    // perspective grid
    ctx.save();
    ctx.strokeStyle = 'rgba(80,140,230,0.12)';
    ctx.lineWidth = 1;
    const t = this.time;
    for (let i = 0; i < 12; i++) {
      const y = TOP + ((i * 64 + t * 26) % (BOTTOM - TOP));
      ctx.beginPath(); ctx.moveTo(LEFT, y); ctx.lineTo(RIGHT, y); ctx.stroke();
    }
    for (let x = LEFT; x <= RIGHT; x += 64) {
      ctx.beginPath(); ctx.moveTo(x, TOP); ctx.lineTo(x, BOTTOM); ctx.stroke();
    }
    ctx.restore();

    // border
    ctx.save();
    ctx.strokeStyle = 'rgba(110,200,255,0.5)';
    ctx.lineWidth = 2;
    ctx.shadowColor = '#4f9dff';
    ctx.shadowBlur = 18;
    ctx.strokeRect(LEFT, TOP, RIGHT - LEFT, BOTTOM - TOP);
    ctx.restore();

    // center line
    ctx.save();
    ctx.strokeStyle = 'rgba(140,180,255,0.18)';
    ctx.setLineDash([12, 18]);
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(W / 2, TOP + 10); ctx.lineTo(W / 2, BOTTOM - 10); ctx.stroke();
    ctx.restore();

    // scores
    ctx.save();
    ctx.textAlign = 'center';
    ctx.font = '700 92px "Space Grotesk", sans-serif';
    ctx.fillStyle = 'rgba(111,227,255,0.18)';
    ctx.fillText(String(this.playerScore), W / 2 - 190, 108);
    ctx.fillStyle = 'rgba(255,143,196,0.18)';
    ctx.fillText(String(this.aiScore), W / 2 + 190, 108);
    ctx.font = '600 10px "Inter", sans-serif';
    ctx.fillStyle = 'rgba(160,190,255,0.45)';
    ctx.fillText('PLAYER', W / 2 - 190, 126);
    ctx.fillText('CPU', W / 2 + 190, 126);
    ctx.restore();

    // trails
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (let i = 0; i < this.trail.length; i++) {
      const p = this.trail[i];
      const a = (i / this.trail.length) * 0.5;
      ctx.fillStyle = `rgba(111,227,255,${a})`;
      ctx.beginPath(); ctx.arc(p.x, p.y, this.ball.r * (0.3 + i / this.trail.length * 0.6), 0, TAU); ctx.fill();
    }
    ctx.restore();

    // paddles
    const drawPaddle = (x, y, color) => {
      ctx.save();
      ctx.shadowColor = color;
      ctx.shadowBlur = 24;
      const g = ctx.createLinearGradient(x - PW / 2, 0, x + PW / 2, 0);
      g.addColorStop(0, '#ffffff');
      g.addColorStop(1, color);
      ctx.fillStyle = g;
      rr(ctx, x - PW / 2, y - PH / 2, PW, PH, 7);
      ctx.fill();
      ctx.restore();
    };
    drawPaddle(LEFT, this.playerY, '#6fe3ff');
    drawPaddle(RIGHT, this.aiY, '#ff8fc4');

    // ball
    ctx.save();
    ctx.shadowColor = '#6fe3ff';
    ctx.shadowBlur = 30;
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.arc(this.ball.x, this.ball.y, this.ball.r, 0, TAU); ctx.fill();
    ctx.restore();

    this.particles.draw(ctx);

    if (this.serveTimer > 0) {
      ctx.save();
      ctx.textAlign = 'center';
      ctx.fillStyle = 'rgba(220,235,255,0.75)';
      ctx.font = '600 15px "Inter", sans-serif';
      ctx.letterSpacing = '4px';
      ctx.fillText('SERVE', W / 2, H / 2 + 8);
      ctx.restore();
    }

    ctx.restore();
    vignette(ctx, W, H, 0.5);
    scanlines(ctx, W, H, 0.035);
  }
}

export default {
  id: 'pong',
  title: 'HYPER PONG',
  subtitle: 'ARCADE CLASSIC',
  accent: '#6fe3ff',
  accent2: '#0e2b5c',
  tagline: 'First to seven. Keep the rally alive.',
  drawCover(ctx, w, h) {
    const g = ctx.createLinearGradient(0, 0, 0, h);
    g.addColorStop(0, '#071227');
    g.addColorStop(1, '#03060f');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);
    ctx.strokeStyle = 'rgba(80,140,230,0.15)';
    for (let y = 0; y < h; y += 24) { ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(w, y); ctx.stroke(); }
    ctx.strokeStyle = 'rgba(140,180,255,0.2)';
    ctx.setLineDash([8, 12]);
    ctx.beginPath(); ctx.moveTo(w / 2, h * 0.12); ctx.lineTo(w / 2, h * 0.8); ctx.stroke();
    ctx.setLineDash([]);
    ctx.save();
    ctx.shadowColor = '#6fe3ff';
    ctx.shadowBlur = 26;
    ctx.fillStyle = '#6fe3ff';
    rr(ctx, w * 0.08, h * 0.3, 10, h * 0.26, 5); ctx.fill();
    ctx.fillStyle = '#ff8fc4';
    rr(ctx, w * 0.9, h * 0.42, 10, h * 0.26, 5); ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.arc(w * 0.55, h * 0.46, 14, 0, TAU); ctx.fill();
    ctx.restore();
    ctx.fillStyle = 'rgba(111,227,255,0.16)';
    ctx.font = `700 ${Math.round(w * 0.3)}px "Space Grotesk", sans-serif`;
    ctx.fillText('3', w * 0.18, h * 0.24);
    ctx.fillStyle = 'rgba(255,143,196,0.16)';
    ctx.fillText('5', w * 0.72, h * 0.24);
    ctx.fillStyle = '#ffffff';
    ctx.font = `700 ${Math.round(w * 0.13)}px "Space Grotesk", sans-serif`;
    ctx.fillText('HYPER', w * 0.07, h * 0.84);
    ctx.fillStyle = '#6fe3ff';
    ctx.fillText('PONG', w * 0.07 + w * 0.5, h * 0.84);
    ctx.fillStyle = 'rgba(170,210,255,0.65)';
    ctx.font = `600 ${Math.round(w * 0.045)}px "Inter", sans-serif`;
    ctx.fillText('ARCADE CLASSIC', w * 0.07, h * 0.9);
  },
  create({ audio }) {
    return new Pong(audio);
  },
};

import { clamp, rand, TAU } from '../util.js';
import { W, H, rr, Particles, glowText, scanlines, vignette } from './common.js';

const LEFT = 96;
const RIGHT = W - 96;
const TOP = 158;
const BOTTOM = H - 44;
const ROWS = 6;
const COLS = 12;

class Breakout {
  constructor(audio) {
    this.audio = audio;
    this.reset();
  }

  reset() {
    this.score = 0;
    this.lives = 3;
    this.level = 1;
    this.state = 'playing';
    this.overTitle = 'GAME OVER';
    this.overSub = 'The wall held. One more run?';
    this.time = 0;
    this.shake = 0;
    this.particles = new Particles();
    this.paddle = { x: W / 2, y: H - 96, w: 132, h: 15, target: W / 2, wide: 0 };
    this.balls = [];
    this.powerups = [];
    this.bricks = [];
    this.buildLevel();
    this.resetBall();
  }

  buildLevel() {
    this.bricks = [];
    const gap = 7;
    const bw = (RIGHT - LEFT - gap * (COLS - 1)) / COLS;
    const bh = 27;
    const colors = ['#ff4f9d', '#ff6b8b', '#ffb84f', '#ffe76a', '#6fe3ff', '#9d8bff'];
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        this.bricks.push({
          x: LEFT + c * (bw + gap),
          y: TOP + r * (bh + gap),
          w: bw,
          h: bh,
          hp: r < 2 ? 2 : 1,
          max: r < 2 ? 2 : 1,
          color: colors[r],
          alive: true,
          flash: 0,
        });
      }
    }
  }

  resetBall() {
    this.balls = [{
      x: this.paddle.x,
      y: this.paddle.y - 18,
      vx: 0,
      vy: 0,
      r: 9,
      speed: 500 + (this.level - 1) * 40,
      stuck: true,
    }];
    this.trail = [];
    this.stuckTimer = 0;
  }

  launch() {
    const b = this.balls[0];
    if (!b || !b.stuck) return;
    b.stuck = false;
    const a = rand(-0.5, 0.5);
    b.vx = Math.sin(a) * b.speed;
    b.vy = -Math.cos(a) * b.speed;
    this.audio.tone(480, 0.1, { type: 'square', gain: 0.04, slide: 700 });
  }

  loseLife() {
    this.lives--;
    this.shake = 14;
    this.audio.hit();
    this.particles.burst(this.paddle.x, BOTTOM, '#ff6b8b', 22, 320, 0.7, 3);
    if (this.lives <= 0) {
      this.state = 'over';
      return;
    }
    this.paddle.wide = 0;
    this.resetBall();
  }

  update(dt, input) {
    this.time += dt;
    this.shake = Math.max(0, this.shake - dt * 42);
    this.particles.update(dt, 300, 1.2);
    if (this.state !== 'playing') return;

    const p = this.paddle;
    p.wide = Math.max(0, p.wide - dt);
    p.w = 132 * (p.wide > 0 ? 1.55 : 1);
    if (input.tv.active) p.target = LEFT + input.tv.x * (RIGHT - LEFT);
    else p.target += input.axis.x * 900 * dt;
    p.target = clamp(p.target, LEFT + p.w / 2, RIGHT - p.w / 2);
    p.x += (p.target - p.x) * Math.min(1, dt * 16);
    p.x = clamp(p.x, LEFT + p.w / 2, RIGHT - p.w / 2);

    if (this.balls.length === 1 && this.balls[0].stuck) {
      this.balls[0].x = p.x;
      this.balls[0].y = p.y - 18;
      this.stuckTimer += dt;
      if (input.pressed('action') || input.pressed('up') || this.stuckTimer > 2.2) this.launch();
    }

    if (input.pressed('action') && !this.balls[0]?.stuck) {
      // nothing: action is launch only
    }

    for (let i = this.balls.length - 1; i >= 0; i--) {
      const b = this.balls[i];
      if (b.stuck) continue;
      b.x += b.vx * dt;
      b.y += b.vy * dt;

      if (b.x - b.r < LEFT) { b.x = LEFT + b.r; b.vx = Math.abs(b.vx); this.audio.tone(280, 0.04, { type: 'square', gain: 0.02 }); }
      if (b.x + b.r > RIGHT) { b.x = RIGHT - b.r; b.vx = -Math.abs(b.vx); this.audio.tone(280, 0.04, { type: 'square', gain: 0.02 }); }
      if (b.y - b.r < TOP) { b.y = TOP + b.r; b.vy = Math.abs(b.vy); this.audio.tone(280, 0.04, { type: 'square', gain: 0.02 }); }

      // paddle
      if (b.vy > 0 && b.y + b.r > p.y && b.y - b.r < p.y + p.h && b.x > p.x - p.w / 2 && b.x < p.x + p.w / 2) {
        b.y = p.y - b.r;
        const off = clamp((b.x - p.x) / (p.w / 2), -1, 1);
        const angle = off * 1.05;
        const speed = Math.min(1150, b.speed * 1.02);
        b.speed = speed;
        b.vx = Math.sin(angle) * speed;
        b.vy = -Math.cos(angle) * speed;
        this.audio.tone(560, 0.06, { type: 'square', gain: 0.04 });
        this.particles.burst(b.x, p.y, '#6fe3ff', 8, 160, 0.35, 2);
      }

      // bricks
      for (const br of this.bricks) {
        if (!br.alive) continue;
        const cx = br.x + br.w / 2;
        const cy = br.y + br.h / 2;
        const dx = Math.abs(b.x - cx);
        const dy = Math.abs(b.y - cy);
        if (dx < br.w / 2 + b.r && dy < br.h / 2 + b.r) {
          const ox = br.w / 2 + b.r - dx;
          const oy = br.h / 2 + b.r - dy;
          if (ox < oy) {
            b.vx = b.x < cx ? -Math.abs(b.vx) : Math.abs(b.vx);
            b.x += b.x < cx ? -ox : ox;
          } else {
            b.vy = b.y < cy ? -Math.abs(b.vy) : Math.abs(b.vy);
            b.y += b.y < cy ? -oy : oy;
          }
          br.hp--;
          br.flash = 0.14;
          if (br.hp <= 0) {
            br.alive = false;
            this.score += 100;
            this.audio.tone(700 + Math.random() * 300, 0.05, { type: 'triangle', gain: 0.035 });
            this.particles.burst(cx, cy, br.color, 14, 240, 0.6, 3);
            if (Math.random() < 0.075) {
              this.powerups.push({ x: cx, y: cy, vy: 120, kind: Math.random() < 0.55 ? 'wide' : 'multi', phase: 0 });
            }
          } else {
            this.audio.tone(420, 0.04, { type: 'square', gain: 0.025 });
          }
          break;
        }
      }

      if (b.y - b.r > BOTTOM) {
        this.balls.splice(i, 1);
      }
    }

    if (this.balls.length === 0) this.loseLife();

    // powerups
    for (let i = this.powerups.length - 1; i >= 0; i--) {
      const pk = this.powerups[i];
      pk.y += pk.vy * dt;
      pk.phase += dt * 4;
      if (pk.y > H + 20) { this.powerups.splice(i, 1); continue; }
      if (pk.y > p.y - 10 && pk.y < p.y + 20 && Math.abs(pk.x - p.x) < p.w / 2 + 14) {
        this.powerups.splice(i, 1);
        this.audio.coin();
        if (pk.kind === 'wide') {
          p.wide = 10;
        } else {
          const src = this.balls[0];
          if (src) {
            for (let k = 0; k < 2; k++) {
              const ang = (k ? 1 : -1) * 0.45;
              this.balls.push({
                x: src.x, y: src.y,
                vx: Math.sin(ang) * src.speed, vy: -Math.cos(ang) * src.speed,
                r: src.r, speed: src.speed, stuck: false,
              });
            }
          }
        }
        this.particles.burst(pk.x, pk.y, '#6fe3ff', 12, 180, 0.5, 2.5);
      }
    }

    // level clear
    if (!this.bricks.some((b) => b.alive)) {
      this.level++;
      this.score += 1000;
      this.audio.launch();
      this.buildLevel();
      this.resetBall();
      this.shake = 6;
    }

    for (const br of this.bricks) br.flash = Math.max(0, br.flash - dt);
  }

  draw(ctx) {
    const shx = this.shake ? rand(-this.shake, this.shake) : 0;
    const shy = this.shake ? rand(-this.shake, this.shake) : 0;
    ctx.save();
    ctx.translate(shx, shy);

    const bg = ctx.createLinearGradient(0, 0, 0, H);
    bg.addColorStop(0, '#0a0d1e');
    bg.addColorStop(0.55, '#0a0a22');
    bg.addColorStop(1, '#04060f');
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, W, H);

    // glow blobs
    for (const [x, y, c] of [[W * 0.2, H * 0.3, '255,79,157'], [W * 0.8, H * 0.2, '111,227,255']]) {
      const g = ctx.createRadialGradient(x, y, 10, x, y, 340);
      g.addColorStop(0, `rgba(${c},0.12)`);
      g.addColorStop(1, `rgba(${c},0)`);
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, W, H);
    }

    // playfield frame
    ctx.save();
    ctx.strokeStyle = 'rgba(130,160,255,0.16)';
    ctx.lineWidth = 1;
    ctx.strokeRect(LEFT - 12, TOP - 12, RIGHT - LEFT + 24, BOTTOM - TOP + 24);
    ctx.restore();

    // bricks
    for (const br of this.bricks) {
      if (!br.alive) continue;
      const g = ctx.createLinearGradient(br.x, br.y, br.x, br.y + br.h);
      g.addColorStop(0, br.color);
      g.addColorStop(1, 'rgba(10,12,24,0.9)');
      ctx.save();
      ctx.shadowColor = br.color;
      ctx.shadowBlur = br.flash > 0 ? 30 : 12;
      ctx.fillStyle = br.flash > 0 ? '#ffffff' : g;
      rr(ctx, br.x, br.y, br.w, br.h, 6);
      ctx.fill();
      ctx.shadowBlur = 0;
      ctx.strokeStyle = 'rgba(255,255,255,0.22)';
      ctx.lineWidth = 1;
      ctx.stroke();
      if (br.max > 1) {
        ctx.fillStyle = 'rgba(255,255,255,0.35)';
        ctx.fillRect(br.x + 8, br.y + br.h - 6, (br.w - 16) * (br.hp / br.max), 2);
      }
      ctx.restore();
    }

    // powerups
    for (const pk of this.powerups) {
      ctx.save();
      ctx.translate(pk.x, pk.y + Math.sin(pk.phase) * 3);
      ctx.rotate(pk.phase * 0.4);
      ctx.shadowColor = '#6fe3ff';
      ctx.shadowBlur = 18;
      ctx.strokeStyle = '#6fe3ff';
      ctx.lineWidth = 2;
      rr(ctx, -13, -9, 26, 18, 5);
      ctx.stroke();
      ctx.fillStyle = '#dff8ff';
      ctx.font = '700 11px "Inter", sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(pk.kind === 'wide' ? 'W' : 'M', 0, 4);
      ctx.restore();
    }

    // paddle
    const p = this.paddle;
    ctx.save();
    ctx.shadowColor = '#6fe3ff';
    ctx.shadowBlur = 26;
    const pg = ctx.createLinearGradient(p.x - p.w / 2, 0, p.x + p.w / 2, 0);
    pg.addColorStop(0, 'rgba(111,227,255,0.35)');
    pg.addColorStop(0.5, '#eaffff');
    pg.addColorStop(1, 'rgba(111,227,255,0.35)');
    ctx.fillStyle = pg;
    rr(ctx, p.x - p.w / 2, p.y, p.w, p.h, 7);
    ctx.fill();
    ctx.restore();

    // balls
    for (const b of this.balls) {
      ctx.save();
      ctx.shadowColor = '#ffffff';
      ctx.shadowBlur = 24;
      ctx.fillStyle = '#ffffff';
      ctx.beginPath(); ctx.arc(b.x, b.y, b.r, 0, TAU); ctx.fill();
      ctx.restore();
    }

    this.particles.draw(ctx);

    if (this.balls[0]?.stuck) {
      ctx.save();
      ctx.textAlign = 'center';
      ctx.fillStyle = 'rgba(220,235,255,0.7)';
      ctx.font = '600 13px "Inter", sans-serif';
      ctx.letterSpacing = '3px';
      ctx.fillText('SPACE / A TO LAUNCH', W / 2, H - 148);
      ctx.restore();
    }

    ctx.restore();
    vignette(ctx, W, H, 0.5);
    scanlines(ctx, W, H, 0.035);

    // HUD
    ctx.save();
    ctx.font = '700 11px "Inter", sans-serif';
    ctx.fillStyle = 'rgba(150,190,255,0.6)';
    ctx.letterSpacing = '4px';
    ctx.fillText('SCORE', 54, 62);
    glowText(ctx, String(this.score).padStart(7, '0'), 54, 102, 32, '#eaf4ff', { blur: 14 });
    ctx.fillStyle = 'rgba(150,190,255,0.6)';
    ctx.letterSpacing = '4px';
    ctx.fillText('LEVEL', 262, 62);
    glowText(ctx, String(this.level).padStart(2, '0'), 262, 102, 32, '#6fe3ff', { blur: 14 });
    for (let i = 0; i < 3; i++) {
      ctx.globalAlpha = i < this.lives ? 1 : 0.16;
      ctx.fillStyle = '#6fe3ff';
      ctx.beginPath(); ctx.arc(W - 64 - i * 28, 82, 7, 0, TAU); ctx.fill();
    }
    ctx.globalAlpha = 1;
    if (this.paddle.wide > 0) {
      ctx.textAlign = 'right';
      ctx.font = '600 10px "Inter", sans-serif';
      ctx.fillStyle = '#ffd76a';
      ctx.fillText(`WIDE ${this.paddle.wide.toFixed(1)}s`, W - 54, 116);
    }
    ctx.restore();
  }
}

