function canInteract() {
  if (mode !== 'walk') return false;
  const dx = -0.65 - player.pos.x;
  const dz = -3.9 - player.pos.z;
  const dist = Math.hypot(dx, dz);
  const fwdX = -Math.sin(player.yaw);
  const fwdZ = -Math.cos(player.yaw);
  const dot = dist > 0.001 ? (dx / dist) * fwdX + (dz / dist) * fwdZ : 0;
  return dist < 4.75 && dot > 0.25 && player.pos.z < 2.1;
}

