const { chromium } = require('playwright');

(async () => {
  const index = Number(process.argv[2] || 0);
  const name = process.argv[3] || `game-${index}`;
  const browser = await chromium.launch({
    headless: true,
    args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist'],
  });
  const page = await browser.newPage({ viewport: { width: 960, height: 600 }, deviceScaleFactor: 1 });
  page.on('console', (m) => { if (m.type() === 'error') console.log('CONSOLE ERROR:', m.text()); });
  await page.goto('http://localhost:3002/', { waitUntil: 'domcontentloaded' });
  await page.waitForFunction(() => !!window.playroom, null, { timeout: 15000 });
  await page.evaluate(() => window.playroom.enter());
  await page.waitForTimeout(700);
  await page.evaluate(() => window.playroom.sit());
  await page.waitForFunction(() => window.playroom.mode === 'seated', null, { timeout: 90000 });
  console.log('seated');
  await page.waitForFunction(() => window.playroom.system.state === 'home', null, { timeout: 90000 });
  console.log('home');
  await page.evaluate((i) => window.playroom.launch(i), index);
  await page.waitForFunction(() => window.playroom.system.state === 'game', null, { timeout: 90000 });
  console.log('game');
  await page.waitForTimeout(2500);
  await page.screenshot({ path: `screenshots/${name}.png`, timeout: 90000 });
  console.log('captured', name);
  await browser.close();
})().catch((e) => { console.error(e); process.exit(1); });

